using System;
using System.IO;
using System.Reflection;
using System.Collections.Generic;
using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;

// Editor-only real-render fixture. It observes the actual game queries; no fake HP or damage.
public static class RenderedContactReview {
 const BindingFlags F=BindingFlags.Public|BindingFlags.NonPublic|BindingFlags.Instance;
 [Serializable]public class Frame { public string stage,path,overlay,closeup; public float time,hp,enemyHp; public Vector3 queryA,queryB,contact; public float queryRadius,contactToVisibleMesh;public string nearestMesh; }
 [Serializable]public class Case {public int id;public string name,kind;public int side;public Vector3 start,enemy;public int strafe;public string expected;public ActionState final;public Frame[] frames;public float firstDamageTime=-1;public int hpChanges;}
 [Serializable]public class Result{public string status="ACTUAL_NATIVE_RENDER_REVIEW_REQUIRED";public string revision="polish3-cue-with-polish2-contact-geometry";public string scope="Same actual controller, fixed1/90 steps, AI off, Unity native camera render. Native contact regression, not performance measurement or WebGL/browser/iPhone evidence.";public Case[] cases;public int errors;}
 static object Get(object o,string name)=>o.GetType().GetField(name,F).GetValue(o);
 static object Invoke(object o,string name,params object[] values)=>o.GetType().GetMethod(name,F).Invoke(o,values);
 static object Weapon(CrabActionGame g,int side)=>((Array)Get(Get(g,"player"),"weapons")).GetValue(side);
 static CrabActionGame Make(){typeof(CrabModel).GetField("materials",BindingFlags.Static|BindingFlags.NonPublic).SetValue(null,null);((System.Collections.IDictionary)typeof(CrabModel).GetField("arenaMaterials",BindingFlags.Static|BindingFlags.NonPublic).GetValue(null)).Clear();EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);var g=new GameObject("CrabActionGame").AddComponent<CrabActionGame>();g.crabShader=Shader.Find("CustomCrabBattle/ChitinR3");g.groundShader=Shader.Find("Standard");g.aiEnabled=false;g.Initialize();return g;}
 static Case Spec(int id,string kind,int side,Vector3 p,Vector3 e,int strafe,string expected,string suffix)=>new Case{id=id,name=kind+"-"+(side==0?"left":"right")+"-"+suffix,kind=kind,side=side,start=p,enemy=e,strafe=strafe,expected=expected};
 static Texture2D Grab(Camera c){var rt=RenderTexture.GetTemporary(768,512,24,RenderTextureFormat.ARGB32,RenderTextureReadWrite.sRGB);var old=c.targetTexture;var prior=RenderTexture.active;c.targetTexture=rt;c.Render();RenderTexture.active=rt;var t=new Texture2D(768,512,TextureFormat.RGB24,false);t.ReadPixels(new Rect(0,0,768,512),0,0);t.Apply();c.targetTexture=old;RenderTexture.active=prior;RenderTexture.ReleaseTemporary(rt);return t;}
 static void Save(Camera c,string path){var t=Grab(c);File.WriteAllBytes(path,t.EncodeToJPG(90));UnityEngine.Object.DestroyImmediate(t);}
 static void Line(Transform parent,Vector3[] points,Color color,bool loop=false){var obj=new GameObject("QA query overlay (non-colliding)");obj.transform.SetParent(parent);var l=obj.AddComponent<LineRenderer>();l.useWorldSpace=true;l.loop=loop;l.positionCount=points.Length;l.SetPositions(points);l.startWidth=l.endWidth=.025f;l.sharedMaterial=new Material(Shader.Find("Hidden/Internal-Colored"));l.startColor=l.endColor=color;l.sharedMaterial.SetInt("_ZTest",(int)UnityEngine.Rendering.CompareFunction.Always);l.sharedMaterial.SetInt("_ZWrite",0);l.sharedMaterial.SetInt("_Cull",(int)UnityEngine.Rendering.CullMode.Off);l.sharedMaterial.SetInt("_SrcBlend",(int)UnityEngine.Rendering.BlendMode.SrcAlpha);l.sharedMaterial.SetInt("_DstBlend",(int)UnityEngine.Rendering.BlendMode.OneMinusSrcAlpha);}
 static void Capsule(Transform parent,Vector3 a,Vector3 b,float radius,Color color){Vector3 n=(b-a).normalized;if(n.sqrMagnitude<.1f)n=Vector3.up;var x=Vector3.Cross(n,Mathf.Abs(n.y)>.9f?Vector3.right:Vector3.up).normalized;var y=Vector3.Cross(n,x).normalized;foreach(var p in new[]{a,b}){var circle=new Vector3[32];for(int i=0;i<32;i++)circle[i]=p+(x*Mathf.Cos(i*Mathf.PI/16)+y*Mathf.Sin(i*Mathf.PI/16))*radius;Line(parent,circle,color,true);}foreach(var axis in new[]{x,y,-x,-y})Line(parent,new[]{a+axis*radius,b+axis*radius},color);}
 static float VisibleDistance(Transform target,Vector3 point,out string name){float best=float.PositiveInfinity;name="";foreach(var mf in target.GetComponentsInChildren<MeshFilter>()){if(!mf.gameObject.activeInHierarchy)continue;var m=mf.sharedMesh;if(!m)continue;var v=m.vertices;var tris=m.triangles;for(int k=0;k<tris.Length;k+=3){var a=mf.transform.TransformPoint(v[tris[k]]);var b=mf.transform.TransformPoint(v[tris[k+1]]);var c=mf.transform.TransformPoint(v[tris[k+2]]);float d=(Closest(point,a,b,c)-point).sqrMagnitude;if(d<best){best=d;name=mf.name;}}}return Mathf.Sqrt(best);}
 static Vector3 Closest(Vector3 p,Vector3 a,Vector3 b,Vector3 c){var ab=b-a;var ac=c-a;var ap=p-a;float d1=Vector3.Dot(ab,ap),d2=Vector3.Dot(ac,ap);if(d1<=0&&d2<=0)return a;var bp=p-b;float d3=Vector3.Dot(ab,bp),d4=Vector3.Dot(ac,bp);if(d3>=0&&d4<=d3)return b;float vc=d1*d4-d3*d2;if(vc<=0&&d1>=0&&d3<=0)return a+ab*(d1/(d1-d3));var cp=p-c;float d5=Vector3.Dot(ab,cp),d6=Vector3.Dot(ac,cp);if(d6>=0&&d5<=d6)return c;float vb=d5*d2-d1*d6;if(vb<=0&&d2>=0&&d6<=0)return a+ac*(d2/(d2-d6));float va=d3*d6-d5*d4;if(va<=0&&(d4-d3)>=0&&(d5-d6)>=0)return b+(c-b)*((d4-d3)/((d4-d3)+(d5-d6)));float denom=1/(va+vb+vc);return a+ab*(vb*denom)+ac*(vc*denom);}
 static Frame Capture(CrabActionGame g,Case spec,string stage,Vector3 a,Vector3 b,float radius,Vector3 contact,bool hit){Invoke(g,"UpdateCamera",1f,true);var f=new Frame{stage=stage,time=g.State().time,hp=g.State().hp,enemyHp=g.State().enemyHp,queryA=a,queryB=b,queryRadius=radius,contact=contact,contactToVisibleMesh=-1};string stem=spec.id.ToString("00")+"-"+spec.name+"-"+stage;f.path="rendered-03/"+stem+".jpg";Save(g.ReviewCamera,"../evidence/"+f.path);if(hit){float priorSize=g.ReviewCamera.orthographicSize;g.ReviewCamera.orthographicSize*=.60f;f.closeup="rendered-03/"+stem+"-close.jpg";Save(g.ReviewCamera,"../evidence/"+f.closeup);g.ReviewCamera.orthographicSize=priorSize;}
  var target=(CrabModel)Get(Get(g,"enemy"),"model");if(hit)f.contactToVisibleMesh=VisibleDistance(target.Root,contact,out f.nearestMesh);
  var overlay=new GameObject("DIAGNOSTIC OVERLAY ONLY");Capsule(overlay.transform,a,b,Mathf.Max(.02f,radius),Color.cyan);var body=(CapsuleCollider)Get(Get(g,"enemy"),"collider");Vector3 center=body.transform.TransformPoint(body.center),dy=body.transform.up*(body.height*.5f-body.radius);Capsule(overlay.transform,center-dy,center+dy,body.radius,new Color(1,.3f,.3f));if(hit){Line(overlay.transform,new[]{contact-Vector3.up*.3f,contact+Vector3.up*.3f},Color.yellow);Line(overlay.transform,new[]{contact-Vector3.right*.3f,contact+Vector3.right*.3f},Color.yellow);}f.overlay="rendered-03/"+stem+"-query.jpg";Save(g.ReviewCamera,"../evidence/"+f.overlay);foreach(var l in overlay.GetComponentsInChildren<LineRenderer>())UnityEngine.Object.DestroyImmediate(l.sharedMaterial);UnityEngine.Object.DestroyImmediate(overlay);return f;
 }
 public static void Run(){Directory.CreateDirectory("../evidence/rendered-03");var specs=new List<Case>();int id=0;
  foreach(string kind in new[]{"sword","cannon","creature"})foreach(int side in new[]{0,1})foreach(bool hit in new[]{true,false}){float d=kind=="cannon"?6:kind=="creature"?2.7f:2.15f;var enemy=hit?new Vector3(0,0,d):kind=="cannon"?new Vector3(5,0,6):new Vector3(0,0,7);specs.Add(Spec(++id,kind,side,Vector3.zero,enemy,0,hit?"one-hit":"whiff",hit?"stationary-contact":"whiff"));}
  foreach(string kind in new[]{"sword","cannon","creature"})foreach(int direction in new[]{-1,1})specs.Add(Spec(++id,kind,0,Vector3.zero,new Vector3(0,0,3),direction,"at-most-one-hit; visual review determines contact", "maximum-strafe-"+direction));
  specs.Add(Spec(++id,"sword",0,new Vector3(8,0,-1.5f),new Vector3(8,0,.65f),0,"one-hit","wall"));specs.Add(Spec(++id,"cannon",1,new Vector3(0,0,2),new Vector3(0,0,8.3f),0,"one-hit","wall"));
  // Two extra explicit projectile boundary observations, outside the core20.
  specs.Add(Spec(++id,"cannon",1,Vector3.zero,new Vector3(0,0,6),0,"one-hit","muzzle-initial-overlap"));specs.Add(Spec(++id,"cannon",0,Vector3.zero,new Vector3(0,0,1.45f),0,"whiff","muzzle-past-target"));
  int errors=0;Application.LogCallback log=(text,stack,type)=>{if(type==LogType.Error||type==LogType.Exception||type==LogType.Assert)errors++;};Application.logMessageReceived+=log;
  try{var g=Make();foreach(var spec in specs){g.Customize("");g.Configure(JsonUtility.ToJson(new ActionConfig{left=spec.kind,right=spec.kind}));g.Begin("");g.ReviewPlace(spec.start,spec.enemy);
   if(spec.name.EndsWith("initial-overlap")){var tip=(Transform)Get(Weapon(g,spec.side),"tip");spec.enemy=new Vector3(tip.position.x,0,tip.position.z);g.ReviewPlace(spec.start,spec.enemy);}
   var frames=new List<Frame>();Vector3 qa=Vector3.zero,qb=Vector3.zero;float qr=0;bool active=false,firstHit=false;
   frames.Add(Capture(g,spec,"ready",qa,qb,0,Vector3.zero,false));
   g.ReviewObserver=(stage,a,b,r)=>{if(stage=="hit"){if(!firstHit){firstHit=true;spec.firstDamageTime=g.State().time;frames.Add(Capture(g,spec,"pre-damage-contact",qa,qb,qr,a,true));}}else {qa=a;qb=b;qr=r;if(!active){active=true;frames.Add(Capture(g,spec,"first-active-query",a,b,r,Vector3.zero,false));}}};
   if(spec.strafe!=0)g.Move(spec.strafe+",0");if(spec.side==0)g.AttackLeft("");else g.AttackRight("");float previous=100;
   for(int frame=0;frame<180;frame++){g.Tick(1f/90);float hp=g.State().enemyHp;if(hp!=previous){spec.hpChanges++;previous=hp;}if(frame==14)frames.Add(Capture(g,spec,"windup",qa,qb,qr,Vector3.zero,false));if(frame==34)frames.Add(Capture(g,spec,"active-motion",qa,qb,qr,Vector3.zero,false));}
   g.Move("0,0");g.ReviewObserver=null;spec.final=g.State();frames.Add(Capture(g,spec,"end",qa,qb,qr,Vector3.zero,false));spec.frames=frames.ToArray();float damage=spec.kind=="sword"?28:spec.kind=="cannon"?24:19;
   if(spec.hpChanges>1||spec.final.hits>1||(spec.final.enemyHp!=100&&spec.final.enemyHp!=100-damage))throw new Exception("Invalid multiple damage: "+spec.name);if(spec.expected=="one-hit"&&spec.final.hits!=1)throw new Exception("Expected contact: "+spec.name);if(spec.expected=="whiff"&&spec.final.hits!=0)throw new Exception("Expected whiff: "+spec.name);
  }}finally{Application.logMessageReceived-=log;File.WriteAllText("../evidence/rendered-contact-review-03.json",JsonUtility.ToJson(new Result{cases=specs.ToArray(),errors=errors},true));}if(errors>0)throw new Exception("Render diagnostic errors: "+errors);
 }
}
